mapper.select:
SELECT comm_num, board_num,bwriter,member_num,bcontent,reip,bcdate, row_num FROM (
SELECT comm_num, board_num,bwriter,member_num,bcontent,reip,bcdate, ROW_NUMBER() 
OVER(ORDER BY comm_num desc) AS row_num FROM BOARD_comm where board_num=#{board_num}
) numbered_rows WHERE row_num BETWEEN #{begin} AND #{end}

mapper.update:
UPDATE BOARD 
SET comm_count = comm_count + 1 
WHERE num = #{num}

UPDATE BOARD 
SET comm_count = comm_count - 1 
WHERE num = #{num}
